const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const dateStr = '2016-01-13';
    const start = ee.Date(dateStr);
    const end = start.advance(1, 'day');
    const region = ee.Geometry.Rectangle({coords: [-180, -68, 180, -56], geodesic: false});
    const scale = 4000;
    const bloomThreshold = 1.0; // mg m^-3 chlorophyll-a
    const yesPercentThreshold = 1.0; // % of valid pixels above threshold to call a bloom "visible"

    // 2. Data Acquisition & Check with fallback
    async function getImageFrom(collectionId, startDate, endDate) {
      const col = ee.ImageCollection(collectionId).filterDate(startDate, endDate).select('chlor_a');
      const size = await col.size().getInfo();
      return {size, img: size > 0 ? col.first() : null, collectionId, startDate, endDate};
    }

    // Primary: MODIS-Aqua L3SMI daily
    let result = await getImageFrom('NASA/OCEANDATA/MODIS-Aqua/L3SMI', start, end);

    // Fallback 1: VIIRS-SNPP L3SMI daily (same date)
    if (result.size === 0) {
      result = await getImageFrom('NASA/OCEANDATA/VIIRS-SNPP/L3SMI', start, end);
    }

    // Fallback 2: MODIS-Aqua 3-day window (12–14 Jan)
    if (result.size === 0) {
      result = await getImageFrom('NASA/OCEANDATA/MODIS-Aqua/L3SMI', start.advance(-1, 'day'), end.advance(1, 'day'));
    }

    if (result.size === 0 || !result.img) {
      console.log(`Date: ${dateStr}`);
      console.log('Collection size: 0 (after fallbacks)');
      console.log('C1');
      return;
    }

    const img = result.img;

    // 3. Processing & Pixel counts
    const countDict = await img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 2e9
    }).getInfo();
    const validCount = (countDict && countDict.chlor_a) ? countDict.chlor_a : 0;

    if (!validCount || validCount === 0) {
      console.log(`Date: ${dateStr}`);
      console.log(`Source: ${result.collectionId}`);
      console.log('Valid pixels after masking: 0');
      console.log('C2');
      return;
    }

    const bloomImg = img.gt(bloomThreshold).selfMask();
    const bloomCountDict = await bloomImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 2e9
    }).getInfo();
    const bloomCount = (bloomCountDict && bloomCountDict.chlor_a) ? bloomCountDict.chlor_a : 0;

    const medianDict = await img.reduceRegion({
      reducer: ee.Reducer.median(),
      geometry: region,
      scale: scale,
      maxPixels: 2e9
    }).getInfo();
    const medianChl = medianDict ? medianDict.chlor_a : null;

    // 4. Validation
    if (medianChl === null || !isFinite(medianChl)) {
      console.log(`Date: ${dateStr}`);
      console.log(`Source: ${result.collectionId}`);
      console.log('Median chlor_a invalid');
      console.log('C3');
      return;
    }

    const bloomPct = (bloomCount / validCount) * 100.0;

    // 5. Output concise evidence and final answer
    console.log(`Date: ${dateStr}`);
    console.log(`Source: ${result.collectionId} (images: ${result.size}, window: ${ee.Date(result.startDate).format('YYYY-MM-dd').getInfo()} to ${ee.Date(result.endDate).format('YYYY-MM-dd').getInfo()})`);
    console.log(`Valid px: ${validCount}, Bloom px (>${bloomThreshold} mg m^-3): ${bloomCount} (${bloomPct.toFixed(2)}%)`);
    console.log(`Median chlor_a: ${medianChl.toFixed(2)} mg m^-3`);

    if (!isFinite(bloomPct)) {
      console.log('C3');
    } else if (bloomPct >= yesPercentThreshold) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0,200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
